package dev.codepassion.hapticengine

/**
 * Every pattern's events, copied from the iOS library so both platforms play the same patterns.
 *
 * Each pattern is text, events separated by `;`: a tap as `t,timeMs,intensity,sharpness` and a hold as
 * `h,timeMs,durationMs,intensity,sharpness`, with levels in thousandths. Text rather than thousands of
 * nested constructors, which made the compiler crawl and the class too large to load.
 */
internal object HapticPatternData {
    const val COUNT: Int = 4000
    private const val CHUNK_SIZE = 500

    /** The encoded events of the pattern at [ordinal]. */
    fun encoded(ordinal: Int): String {
        val offset = ordinal % CHUNK_SIZE
        return when (ordinal / CHUNK_SIZE) {
            0 -> HapticPatternData0.encoded[offset]
            1 -> HapticPatternData1.encoded[offset]
            2 -> HapticPatternData2.encoded[offset]
            3 -> HapticPatternData3.encoded[offset]
            4 -> HapticPatternData4.encoded[offset]
            5 -> HapticPatternData5.encoded[offset]
            6 -> HapticPatternData6.encoded[offset]
            7 -> HapticPatternData7.encoded[offset]
            else -> throw IndexOutOfBoundsException("No pattern at $ordinal")
        }
    }
}

